B.U3=s(["\u049b\u0430\u04a3\u0442\u0430\u0440","\u0430\u049b\u043f\u0430\u043d","\u043d\u0430\u0443\u0440\u044b\u0437","\u0441\u04d9\u0443\u0456\u0440","\u043c\u0430\u043c\u044b\u0440","\u043c\u0430\u0443\u0441\u044b\u043c","\u0448\u0456\u043b\u0434\u0435","\u0442\u0430\u043c\u044b\u0437","\u049b\u044b\u0440\u043a\u04af\u0439\u0435\u043a","\u049b\u0430\u0437\u0430\u043d","\u049b\u0430\u0440\u0430\u0448\u0430","\u0436\u0435\u043b\u0442\u043e\u049b\u0441\u0430\u043d"],t.s)
B.lY=s(["\u05d9\u05e0\u05d5\u05f3","\u05e4\u05d1\u05e8\u05f3","\u05de\u05e8\u05e5","\u05d0\u05e4\u05e8\u05f3","\u05de\u05d0\u05d9","\u05d9\u05d5\u05e0\u05d9","\u05d9\u05d5\u05dc\u05d9","\u05d0\u05d5\u05d2\u05f3","\u05e1\u05e4\u05d8\u05f3","\u05d0\u05d5\u05e7\u05f3","\u05e0\u05d5\u05d1\u05f3","\u05d3\u05e6\u05de\u05f3"],t.s)
B.bh=new A.Eh(1,"stimmtNicht")
B.bzL=new A.cW("In der Schwangerschaft musst du f\xfcr zwei essen.",B.bh,"Der Energiebedarf steigt nur wenig: im zweiten Drittel um etwa 250, im dritten um etwa 500 Kilokalorien pro Tag. Das entspricht eher einem Zwischenimbiss als einer zweiten Portion.","Netzwerk Gesund ins Leben")
B.bAb=new A.cW("Kaffee ist in der Schwangerschaft komplett verboten.",B.bh,"Bis zu 200 Milligramm Koffein pro Tag gelten als unbedenklich, das sind etwa zwei bis drei Tassen Kaffee.","Bundesinstitut f\xfcr Risikobewertung")
B.bzJ=new A.cW("Sex schadet dem Baby.",B.bh,"Bei normalem Verlauf schadet Sex dem Baby nicht. Es ist durch Fruchtwasser und Geb\xe4rmuttermuskel gut gesch\xfctzt. Bei Blutungen, vorzeitigen Wehen oder tiefliegendem Mutterkuchen sprich mit deiner \xc4rztin.","Leitlinien der DGGG")
B.bzG=new A.cW("Ein schneller Herzschlag des Babys bedeutet M\xe4dchen.",B.bh,"Die Herzfrequenz des Babys h\xe4ngt vom Alter und Zustand ab, nicht vom Geschlecht. Das Geschlecht l\xe4sst sich per Ultraschall meist ab der 18. bis 22. Woche erkennen.","familienplanung.de (BI\xd6G)")
B.bA1=new A.cW("Ein spitzer Bauch bedeutet Junge, ein runder Bauch M\xe4dchen.",B.bh,"Die Bauchform h\xe4ngt von K\xf6rperbau, Muskulatur, Lage des Babys und davon ab, ob es dein erstes Kind ist. Sie sagt nichts \xfcber das Geschlecht aus.","familienplanung.de (BI\xd6G)")
B.zf=new A.Eh(3,"nichtBelegt")
B.bzZ=new A.cW("Sodbrennen bedeutet, dass das Baby viele Haare hat.",B.zf,"Eine kleine Studie fand einen Zusammenhang, verl\xe4sslich vorherzusagen ist die Haarpracht daraus nicht. Sodbrennen entsteht vor allem durch Hormone und den Druck der Geb\xe4rmutter.","Leitlinien der DGGG")
B.bA3=new A.cW("Sport schadet dem Baby.",B.bh,"Bei unkomplizierter Schwangerschaft wird moderate Bewegung ausdr\xfccklich empfohlen. Verzichten solltest du auf Sportarten mit Sturzrisiko und bei \xe4rztlichem Bewegungsverbot.","Leitlinien der DGGG")
B.bzQ=new A.cW("Wer die Arme \xfcber den Kopf hebt, wickelt die Nabelschnur um das Baby.",B.bh,"Die Nabelschnur schlingt sich unabh\xe4ngig von deinen Armbewegungen um das Baby, weil es sich frei im Fruchtwasser bewegt. Du kannst Arme heben, Regale erreichen und W\xe4sche aufh\xe4ngen.","Deutscher Hebammenverband")
B.kw=new A.Eh(2,"teils")
B.bzE=new A.cW("Du darfst auf dem R\xfccken schlafen, das ist nie ein Problem.",B.kw,"Kurzes Liegen ist kein Problem. In der zweiten H\xe4lfte der Schwangerschaft wird die Seitenlage empfohlen, weil die Geb\xe4rmutter in R\xfcckenlage auf gro\xdfe Blutgef\xe4\xdfe dr\xfccken kann. Wachst du auf dem R\xfccken auf, dreh dich einfach um.","Deutscher Hebammenverband")
B.bzP=new A.cW("Wer schwanger ist, muss die Katze abgeben.",B.bh,"Du musst nur Kontakt zum Katzenkot vermeiden (Toxoplasmose). Lass das Katzenklo von jemand anderem reinigen oder trage Handschuhe und wasche danach gr\xfcndlich die H\xe4nde.","Bundesinstitut f\xfcr Risikobewertung")
B.bA6=new A.cW("Haare f\xe4rben ist in der Schwangerschaft verboten.",B.kw,"Gelegentliches F\xe4rben gilt als unbedenklich, weil nur wenig Farbstoff durch die Kopfhaut in den K\xf6rper gelangt. Wer vorsichtig sein will, wartet bis nach dem ersten Drittel und l\xfcftet gut.","Embryotox (Charit\xe9)")
B.bzz=new A.cW("Schwangere d\xfcrfen nicht fliegen.",B.bh,"Bei unkomplizierter Schwangerschaft ist Fliegen meist bis etwa zur 36. Woche m\xf6glich. Airlines verlangen oft ein Attest ab der 28. bis 32. Woche, trage gegen Thrombose Kompressionsstr\xfcmpfe.","Leitlinien der DGGG")
B.bzX=new A.cW("Das Baby kommt am errechneten Termin.",B.bh,"Nur etwa vier von hundert Babys kommen am errechneten Termin. Als termingerecht gilt jede Geburt zwischen der 37+0 und 41+6 SSW.","Mutterschafts-Richtlinien des G-BA")
B.bA7=new A.cW("Bei Vollmond kommen mehr Babys zur Welt.",B.bh,"Untersuchungen mit tausenden Geburten zeigen keinen Zusammenhang zwischen Mondphase und Geburtenzahl. Der Eindruck entsteht durch selektive Erinnerung.",u.bW)
B.bzD=new A.cW("Jede Schwangerschaft kostet einen Zahn.",B.bh,"Z\xe4hne verlieren in der Schwangerschaft kein Calcium. Allerdings ist das Zahnfleisch empfindlicher, gute Pflege und Kontrolle beim Zahnarzt sind wichtig.","BI\xd6G")
B.bAg=new A.cW("Stillen verh\xfctet zuverl\xe4ssig.",B.bh,"Stillen kann den Eisprung verz\xf6gern, ist aber nur unter sehr engen Bedingungen sicher genug. Der erste Eisprung kommt vor der ersten Periode, du kannst also schwanger werden, ohne es vorher zu merken.","Leitlinien der DGGG")
B.bzF=new A.cW("Stillen l\xe4sst die Br\xfcste h\xe4ngen.",B.bh,"Die Brustform ver\xe4ndert sich vor allem durch die Schwangerschaft selbst, Alter, Gewicht und Veranlagung, nicht durch das Stillen an sich.","Nationale Stillkommission")
B.bzH=new A.cW("Wer nicht stillt, baut keine gute Bindung zum Kind auf.",B.bh,"Bindung entsteht durch N\xe4he, Zuwendung und liebevollen Umgang. Auch mit dem Fl\xe4schchen ist enger K\xf6rperkontakt m\xf6glich und wichtig.","BI\xd6G")
B.bAa=new A.cW("Ein Kaiserschnitt ist der einfachere Weg.",B.bh,"Ein Kaiserschnitt ist eine gro\xdfe Bauchoperation mit l\xe4ngerer Erholung und eigenen Risiken. Er kann medizinisch notwendig und sinnvoll sein, ist aber nicht \u201eeinfacher\u201c.","Leitlinien der DGGG")
B.bA5=new A.cW("Nach einem Kaiserschnitt ist wieder ein Kaiserschnitt n\xf6tig.",B.bh,"Vielen Frauen gelingt nach einem Kaiserschnitt eine vaginale Geburt. Ob sie f\xfcr dich infrage kommt, kl\xe4rt ihr in der Schwangerschaft gemeinsam mit der Klinik.","Leitlinien der DGGG")
B.bzy=new A.cW("Ein Baby braucht Kissen und Decke, um gut zu schlafen.",B.bh,"Kissen, Decken, Nestchen und Kuscheltiere erh\xf6hen die Gefahr des pl\xf6tzlichen Kindstods. Ein Schlafsack in passender Gr\xf6\xdfe auf fester Matratze ist sicher.","BI\xd6G: Sicherer Babyschlaf")
B.bzI=new A.cW("Ein Baby, das viel getragen wird, wird verw\xf6hnt.",B.bh,"Babys k\xf6nnen nicht verw\xf6hnt werden. N\xe4he und rasche Zuwendung geben Sicherheit und f\xf6rdern eine stabile Bindung.","BI\xd6G")
B.bA2=new A.cW("Schreien lassen st\xe4rkt die Lungen.",B.bh,"Schreien lassen hilft nicht, sondern stresst das Baby. Auf Weinen zu reagieren, gibt Sicherheit. Bist du \xfcberfordert, lege dein Baby sicher ab und hole Hilfe.","BI\xd6G")
B.bzW=new A.cW("Zahnen verursacht hohes Fieber und Durchfall.",B.bh,"Beim Zahnen kann es zu Sabbern, Unruhe und leicht erh\xf6hter Temperatur kommen. Hohes Fieber und Durchfall haben eine andere Ursache und sollten abgekl\xe4rt werden.","DGKJ")
B.bzY=new A.cW("Ein Baby schl\xe4ft besser durch, wenn es fr\xfch Brei bekommt.",B.bh,"Fr\xfcher Brei verbessert den Schlaf nachweislich nicht. Beikost beginnt erst, wenn dein Kind bereit ist, fr\xfchestens zu Beginn des 5. Monats. Die Stillleitlinie von 2026 empfiehlt eher etwa sechs Monate Stillen.",u.k)
B.bzK=new A.cW("Impfungen \xfcberlasten das Immunsystem des Babys.",B.bh,"Babys begegnen t\xe4glich unz\xe4hligen Erregern. Impfstoffe belasten das Immunsystem nicht \xfcberm\xe4\xdfig, sie sch\xfctzen vor gef\xe4hrlichen Krankheiten, gerade in den ersten Monaten.","STIKO / Robert Koch-Institut")
B.bzS=new A.cW("Der pl\xf6tzliche Kindstod l\xe4sst sich nicht beeinflussen.",B.bh,"Das Risiko l\xe4sst sich deutlich senken: R\xfcckenlage, sichere Schlafumgebung, kein Rauch, eigener Schlafplatz im Elternzimmer, Stillen und Schnuller.","BI\xd6G: Sicherer Babyschlaf")
B.bzO=new A.cW("Handystrahlung und WLAN schaden dem ungeborenen Baby.",B.zf,"Nach heutigem Wissen gibt es keinen Hinweis auf Sch\xe4den durch allt\xe4gliche Nutzung. Ein dauerhafter Kontakt des Handys mit dem Bauch ist nicht n\xf6tig.","Bundesamt f\xfcr Strahlenschutz")
B.bA_=new A.cW("Ein Glas Rotwein am Abend ist okay.",B.bh,"Es gibt keine nachweislich sichere Alkoholmenge in der Schwangerschaft. Alkohol geht direkt auf das Baby \xfcber und kann bleibende Sch\xe4den verursachen.","BI\xd6G")
B.bzR=new A.cW("Ingwer hilft gegen Schwangerschafts\xfcbelkeit.",B.kw,"Studien zeigen bei manchen eine leichte Linderung. Er ist in \xfcblichen Mengen unbedenklich. Bei starker \xdcbelkeit ist \xe4rztliche Hilfe n\xf6tig.","Leitlinien der DGGG")
B.bzT=new A.cW("Himbeerbl\xe4ttertee erleichtert die Geburt.",B.zf,"Ein klarer Nutzen ist nicht belegt. In \xfcblichen Mengen gilt er als unbedenklich, viele Hebammen empfehlen ihn trotzdem gern in den letzten Wochen.","Deutscher Hebammenverband")
B.bzU=new A.cW("Dammmassage senkt das Risiko f\xfcr einen Dammriss.",B.kw,"Bei Erstgeb\xe4renden kann Dammmassage ab der 34. Woche die Wahrscheinlichkeit f\xfcr schwere Risse und Dammschnitte etwas senken. Sie ist freiwillig.","Deutscher Hebammenverband")
B.bA0=new A.cW("Ab dem errechneten Termin muss eingeleitet werden.",B.bh,"Am Termin wird h\xe4ufiger kontrolliert. Eine Einleitung wird meist ab 41+0 angeboten, sp\xe4testens bei Risiken. Ob und wann du einleiten lassen willst, entscheidest du nach Beratung.","Leitlinien der DGGG")
B.bA4=new A.cW("Zwillinge \xfcberspringen eine Generation.",B.bh,"Zweieiige Zwillinge kommen famili\xe4r geh\xe4uft vor, meist \xfcber die Mutterseite, ohne dass eine Generation \xfcbersprungen w\xfcrde. Eineiige Zwillinge sind reiner Zufall.","Pschyrembel")
B.bAf=new A.cW("Neugeborene sehen nur in Schwarz-Wei\xdf.",B.kw,"Neugeborene sehen anfangs verschwommen und erkennen kontrastreiche Muster am besten. Das Farbsehen entwickelt sich in den ersten Monaten. Auf 20 bis 30 Zentimeter sehen sie am sch\xe4rfsten.","Kinder\xe4rzte im Netz")
B.bzB=new A.cW("Ein Baby muss nach dem Essen immer aufsto\xdfen.",B.kw,"Ein B\xe4uerchen kann Bl\xe4hungen lindern, ist aber nicht bei jeder Mahlzeit n\xf6tig. Viele gestillte Babys schlucken wenig Luft. Wenn dein Baby zufrieden ist, brauchst du nicht lange zu warten.","Kinder\xe4rzte im Netz")
B.bzA=new A.cW("Die erste Milch, das Kolostrum, ist minderwertig.",B.bh,"Das Kolostrum ist konzentrierte, an Abwehrstoffen reiche Milch. In kleinen Mengen ist es genau das, was ein Neugeborenes in den ersten Tagen braucht.","Nationale Stillkommission")
B.bA9=new A.cW("Bl\xe4hende Lebensmittel machen das Baby beim Stillen unruhig.",B.bh,"Was du isst, geht nicht in Form von Luft in die Milch \xfcber. Bei Bauchweh des Babys spielt selten deine Ern\xe4hrung eine Rolle. Bei Verdacht auf Unvertr\xe4glichkeit sprich mit der Kinder\xe4rztin.","Nationale Stillkommission")
B.bzC=new A.cW("Sonnenlicht heilt Neugeborenengelbsucht.",B.bh,"Direkte Sonne ist f\xfcr Neugeborene gef\xe4hrlich und keine Behandlung. Eine Gelbsucht wird \xe4rztlich kontrolliert und bei Bedarf mit Lichttherapie unter medizinischer Aufsicht behandelt.","DGKJ")
B.bAe=new A.cW("Wer Gestationsdiabetes hat, bekommt automatisch ein krankes Baby.",B.bh,"Mit Ern\xe4hrung, Bewegung und ggf. Insulin l\xe4sst sich der Blutzucker meist gut einstellen. Unbehandelt kann das Baby zu gro\xdf werden, deshalb ist die Kontrolle wichtig.","Leitlinien der DGGG")
B.bzM=new A.cW("Ohne Schmerzmittel ist eine Geburt \u201erichtiger\u201c.",B.bh,"Es gibt kein richtig oder falsch. Wie du mit Schmerzen umgehst, entscheidest du. Zur Wahl stehen Atmung, Wasser, Massage, Lachgas, PDA und mehr.","Deutscher Hebammenverband")
B.bAd=new A.cW("Schwangere d\xfcrfen nicht die Haare schneiden oder baden.",B.bh,"Haarschneiden und ein warmes Bad sind kein Problem. Sehr hei\xdfe B\xe4der und Saunag\xe4nge solltest du im ersten Drittel meiden.","Leitlinien der DGGG")
B.bzN=new A.cW("Am Ende der Schwangerschaft sollte man sich nur noch schonen.",B.bh,"Bewegung ist weiter gut, Spazierg\xe4nge und leichte Gymnastik tun Kreislauf und Stimmung gut. Als sichere Methode, Wehen auszul\xf6sen, taugt sie allerdings nicht.","Deutscher Hebammenverband")
B.bA8=new A.cW("Wer nicht lange stillt, macht etwas falsch.",B.bh,"Jede Stillzeit ist wertvoll. Die neue S3-Leitlinie von 2026 empfiehlt etwa sechs Monate ausschlie\xdfliches oder \xfcberwiegendes Stillen und insgesamt mindestens zw\xf6lf Monate. Das ist eine Empfehlung, kein Ma\xdfstab f\xfcr dich als Mutter. Klappt Stillen nicht oder m\xf6chtest du nicht, ist Pre-Nahrung eine gute Alternative.",u.R)
B.bAc=new A.cW("Nach der Geburt geh\xf6rt man sofort wieder in Form.",B.bh,"Der K\xf6rper braucht Zeit. Wochenbett und R\xfcckbildung dauern Wochen bis Monate. Ein langsamer Wiedereinstieg sch\xfctzt Beckenboden und Bauchmuskeln.","Deutscher Hebammenverband")
B.bzV=new A.cW("Man kann das Geschlecht am Herzschlag oder an Hei\xdfhunger erkennen.",B.bh,"Weder Hei\xdfhunger auf S\xfc\xdfes oder Saures noch andere Beobachtungen sagen das Geschlecht voraus. Sicher sind nur Ultraschall (ab etwa der 18. Woche) und Erbgutuntersuchungen.","familienplanung.de (BI\xd6G)")
